// The 21 May – 20 Jul 2026 case with rules, and the all-window evidence. Generated by
// lp_study/export_rules_case.py from every real swap of Uniswap mainnet ETH/USDC 0.05%
// (rule_search.py: fees replayed per swap, $1.50 gas + keeper per action, pool fee on every swap).
import data from "./rulesCase.json";

export type Row = {
  t: number;
  px: number;
  plain: number;
  hold: number;
  rerange: number;
  stop: number;
  alucard: number;
  state: string;
  eth_share: number | null;
  range: number[] | null;
};

export const CASE = data as unknown as {
  finals: Record<"plain" | "rerange" | "stop" | "alucard" | "hold", { final: number; actions?: number; fees?: number; costs?: number }>;
  events: { t: number; px: number; kind: string; value: number }[];
  path: Row[];
  windows: Record<string, { n?: number; beat_hold?: number; beat_plain?: number; mean_final: number; down: { n?: number; beat_hold?: number; mean: number }; up: { n?: number; beat_hold?: number; mean: number } }> & {
    grid: { trend_configs: number; trend_configs_beating_hold_on_average: number; trend_configs_beating_plain_on_average: number };
  };
};

export const DEPOSIT = 600;
const P = CASE.path;

/** Every column at time t (days), linearly interpolated; the rule state is the one in force at t. */
export function caseAt(t: number) {
  let i = 0;
  while (i < P.length - 2 && P[i + 1].t <= t) i++;
  const a = P[i];
  const b = P[Math.min(i + 1, P.length - 1)];
  const f = b.t > a.t ? Math.min(1, Math.max(0, (t - a.t) / (b.t - a.t))) : 0;
  const m = (k: "px" | "plain" | "hold" | "rerange" | "stop" | "alucard") => a[k] + (b[k] - a[k]) * f;
  const now = t >= b.t ? b : a;
  return { t, px: m("px"), plain: m("plain"), hold: m("hold"), rerange: m("rerange"), stop: m("stop"), alucard: m("alucard"), state: now.state, ethShare: now.eth_share, range: now.range };
}

/** The ranges the rule set held, as time segments: [from, to, lo, hi]. */
export const SEGMENTS: [number, number, number, number][] = (() => {
  const out: [number, number, number, number][] = [];
  for (let i = 1; i < P.length; i++) {
    const r = P[i].range;
    const prev = out[out.length - 1];
    if (r && prev && prev[2] === r[0] && prev[3] === r[1] && prev[1] === P[i - 1].t) prev[1] = P[i].t;
    else if (r) out.push([P[i - 1].t, P[i].t, r[0], r[1]]);
  }
  return out;
})();

/** Time segments by what the rule set was holding: in a range, in USDC, or riding ETH. */
export const STATES: [number, number, string][] = (() => {
  const out: [number, number, string][] = [];
  for (let i = 1; i < P.length; i++) {
    const s = P[i].state;
    const prev = out[out.length - 1];
    if (prev && prev[2] === s) prev[1] = P[i].t;
    else out.push([P[i - 1].t, P[i].t, s]);
  }
  return out;
})();
